/* Design tokens and the web font. Every other stylesheet uses these. */

@font-face {
  font-family: 'Acme Sans';
  src: url('../fonts/acme-sans.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

:root {
  --color-ink: #1f2328;
  --color-muted: #59636e;
  --color-line: #d8dee4;
  --color-bg: #f6f8fa;
